package com.tiviloom.mobile;
import android.graphics.*;import android.os.*;import android.widget.ImageView;import java.net.*;import java.io.*;import java.lang.ref.WeakReference;import java.util.concurrent.*;
/** Bounded logo cache; provider images never block the UI or decoder thread. */
final class ChannelLogos {
 private final android.util.LruCache<String,Bitmap> cache=new android.util.LruCache<String,Bitmap>(4096){@Override protected int sizeOf(String key,Bitmap bitmap){return Math.max(1,bitmap.getByteCount()/1024);}};
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(2,2,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(24),new ThreadPoolExecutor.DiscardPolicy());private final Handler main=new Handler(Looper.getMainLooper());private volatile boolean closed;
 void load(String url,ImageView image){if(url==null||url.length()>4000||closed)return;image.setTag(url);Bitmap hit=cache.get(url);if(hit!=null){image.setImageBitmap(hit);return;}WeakReference<ImageView> target=new WeakReference<>(image);worker.execute(()->{HttpURLConnection connection=null;try{URL parsed=new URL(url);if(!java.util.Arrays.asList("http","https").contains(parsed.getProtocol())||parsed.getUserInfo()!=null)return;connection=(HttpURLConnection)parsed.openConnection();connection.setConnectTimeout(4000);connection.setReadTimeout(4000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("User-Agent","TiviLoom/"+BuildConfig.VERSION_NAME);if(connection.getResponseCode()!=200)return;if(connection.getContentLengthLong()>1048576)return;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=connection.getInputStream()){byte[] block=new byte[8192];int n;while((n=input.read(block))!=-1){if(closed||bytes.size()+n>1048576)return;bytes.write(block,0,n);}}byte[] raw=bytes.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(options.outWidth<1||options.outHeight<1||options.outWidth>12000||options.outHeight>12000)return;options.inSampleSize=Math.max(1,Math.max(options.outWidth,options.outHeight)/96);options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(bitmap==null||closed)return;cache.put(url,bitmap);main.post(()->{ImageView v=target.get();if(!closed&&v!=null&&url.equals(v.getTag())){v.setBackgroundColor(0xFF0C293B);v.setImageBitmap(bitmap);}});}catch(Exception ignored){}finally{if(connection!=null)connection.disconnect();}});}
 void cancelPending(){worker.getQueue().clear();}
 void close(){closed=true;worker.shutdownNow();main.removeCallbacksAndMessages(null);cache.evictAll();}
}
